{
  "skeleton": "lost_acolyte",
  "actor_zh": "一名濕漉漉、渾身顫抖的道童",
  "motive_zh": "害怕在濃霧中徹底失去方向，想要盡快回到青霧觀。",
  "text_zh": "梯田的水氣混著濃霧，把四周的景物都吞沒了。\n一道細小的身影跌坐在泥水裡，小蓮抬起頭，看著你，眼眶泛紅地喊：「哥哥，我找不到回家的路了……」",
  "more_zh": "","npcs":["acolyte_xiaolian"],"locations":["rain_terraces"],"threads":[]}

{
  "skeleton": "wounded_peddler",
  "actor_zh": "一名腿上帶傷、肩扛破貨的行商",
  "motive_zh": "想趕在霧狼群出沒前回到霧渡鎮，保住僅剩的貨物與性命。",
  "text_zh": "雨霧漫過梯田階沿，一個行商跌坐泥裡，左腿滲血。他抬頭看你，眼神驚惶：「霧狼快來了……」",
  "more_zh": "","npcs":[],"locations":["rain_terraces"],"threads":[]}

{
  "skeleton": "fox_traveler",
  "actor_zh": "一名蹲在田埂邊、耳尖顫動的狐族旅人",
  "motive_zh": "腹中飢餓難耐，想換些乾糧果腹，卻怕被人類抓去獻祭。",
  "text_zh": "霧氣漫過梯田，斷裂的界域在遠處浮沉。\n田埂邊蹲著一名狐族旅人，她緊握著破舊的背囊，獸耳警惕地轉動。","more_zh":"她的目光在你身上停留片刻，隨即別開去，喉嚨間發出一聲低沉的不安響動。","npcs":[],"locations":["rain_terraces"],"threads":[]}

